    "argument": "site:hse.gov.uk OR site:thegazette.co.uk OR site:fca.org.uk OR site:gov.uk — search: 'Option Energy Solutions' Steyning OR 08893883 HSE OR 'Trading Standards' OR 'Environment Agency' OR FCA OR prosecution OR 'enforcement notice'",
    "question_id": "Q10",
    "tool": "web_search"
